solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <map>
#include <set>
#include <string>
#include <vector>

struct PluginFile
{
    std::string name;
    uint32_t apiVersion{ 1 };
    std::vector<std::string> requires_;
    std::vector<std::string> provides;
};

class Host
{
public:
    explicit Host(uint32_t apiVersion) : m_api{ apiVersion } {}

    void addFile(const PluginFile& file) { m_files[file.name] = file; }

    std::vector<std::string> startAll()
    {
        std::vector<std::string> log;
        std::set<std::string> logged, visiting;
        for (const auto& [name, file] : m_files) start(name, log, logged, visiting);
        return log;
    }

    std::vector<std::string> reload(const std::string& name)
    {
        std::vector<std::string> log;
        if (isRunning(name))
        {
            for (auto it{ m_running.rbegin() }; it != m_running.rend();)
            {
                const std::string p{ *it };
                if (p == name || dependsOn(p, name, {}))
                {
                    log.push_back("stop " + p);
                    unregister(p);
                    it = std::make_reverse_iterator(m_running.erase(std::next(it).base()));
                }
                else ++it;
            }
        }
        const auto more{ startAll() };
        log.insert(log.end(), more.begin(), more.end());
        return log;
    }

    std::vector<std::string> running() const { return m_running; }

    std::string providerOf(const std::string& id) const
    {
        const auto it{ m_registry.find(id) };
        return it == m_registry.end() ? "" : it->second;
    }

private:
    bool isRunning(const std::string& name) const { return std::find(m_running.begin(), m_running.end(), name) != m_running.end(); }

    bool dependsOn(const std::string& plugin, const std::string& target, std::set<std::string> seen) const
    {
        if (!seen.insert(plugin).second) return false;
        const auto it{ m_files.find(plugin) };
        if (it == m_files.end()) return false;
        for (const std::string& r : it->second.requires_)
            if (r == target || dependsOn(r, target, seen)) return true;
        return false;
    }

    void unregister(const std::string& owner)
    {
        for (auto it{ m_registry.begin() }; it != m_registry.end();)
            it = it->second == owner ? m_registry.erase(it) : std::next(it);
    }

    void skip(const std::string& name, const std::string& why, std::vector<std::string>& log, std::set<std::string>& logged)
    {
        if (logged.insert(name).second) log.push_back("skip " + name + ": " + why);
    }

    // Returns whether the plugin is running afterwards.
    bool start(const std::string& name, std::vector<std::string>& log, std::set<std::string>& logged, std::set<std::string>& visiting)
    {
        if (isRunning(name)) return true;
        if (logged.count(name)) return false;              // already failed in this round
        const PluginFile& file{ m_files.at(name) };
        if (file.apiVersion != m_api) { skip(name, "API version " + std::to_string(file.apiVersion) + ", need " + std::to_string(m_api), log, logged); return false; }
        visiting.insert(name);
        for (const std::string& r : file.requires_)
        {
            if (!m_files.count(r)) { visiting.erase(name); skip(name, "needs " + r, log, logged); return false; }
            if (visiting.count(r)) { visiting.erase(name); skip(name, "cycle", log, logged); return false; }
            if (!start(r, log, logged, visiting)) { visiting.erase(name); skip(name, "needs " + r, log, logged); return false; }
        }
        visiting.erase(name);
        std::vector<std::string> added;
        for (const std::string& id : file.provides)
        {
            std::string problem;
            if (id.rfind(name + ".", 0) != 0 || id.size() <= name.size() + 1) problem = id + " is not " + name + ".*";
            else if (m_registry.count(id)) problem = id + " is taken";
            if (!problem.empty())
            {
                for (const std::string& a : added) m_registry.erase(a);
                skip(name, problem, log, logged);
                return false;
            }
            m_registry[id] = name;
            added.push_back(id);
        }
        m_running.push_back(name);
        logged.insert(name);
        log.push_back("start " + name);
        return true;
    }

    uint32_t m_api;
    std::map<std::string, PluginFile> m_files;
    std::vector<std::string> m_running;
    std::map<std::string, std::string> m_registry;
};

unitTests:
using Lines = std::vector<std::string>;
PluginFile P(const char* name, std::vector<std::string> req, std::vector<std::string> prov, uint32_t api = 1) { PluginFile f; f.name = name; f.apiVersion = api; f.requires_ = req; f.provides = prov; return f; }
Host sample() {
    Host h{ 1 };
    h.addFile(P("fog", {}, { "fog.ghost_stone", "fog.thickness" }));
    h.addFile(P("seasons", { "fog", "weather" }, { "seasons.winter" }));
    h.addFile(P("weather", {}, { "weather.rain" }));
    h.addFile(P("storms", { "weather", "wind" }, {}));
    h.addFile(P("old", {}, {}, 0));
    return h;
}
TEST("start everything") {
    Host h = sample();
    CHECK_EQ(h.startAll(), (Lines{ "start fog", "skip old: API version 0, need 1", "start weather", "start seasons", "skip storms: needs wind" }));
    CHECK_EQ(h.running(), (Lines{ "fog", "weather", "seasons" }));
    CHECK_EQ(h.providerOf("fog.thickness"), std::string("fog")); CHECK_EQ(h.providerOf("seasons.winter"), std::string("seasons")); CHECK_EQ(h.providerOf("storms.x"), std::string(""));
}
TEST("starting again starts nothing new") { Host h = sample(); h.startAll(); CHECK_EQ(h.startAll(), (Lines{ "skip old: API version 0, need 1", "skip storms: needs wind" })); }
TEST("reload stops dependents first") {
    Host h = sample(); h.startAll();
    h.addFile(P("fog", {}, { "fog.ghost_stone", "fog.mist" }));
    CHECK_EQ(h.reload("fog"), (Lines{ "stop seasons", "stop fog", "start fog", "skip old: API version 0, need 1", "start seasons", "skip storms: needs wind" }));
    CHECK_EQ(h.running(), (Lines{ "weather", "fog", "seasons" }));
    CHECK_EQ(h.providerOf("fog.thickness"), std::string("")); CHECK_EQ(h.providerOf("fog.mist"), std::string("fog"));
}
TEST("a clash rolls back") {
    Host h{ 1 };
    h.addFile(P("a", {}, { "a.one" }));
    h.addFile(P("b", {}, { "b.one", "a.one" }));
    CHECK_EQ(h.startAll(), (Lines{ "start a", "skip b: a.one is not b.*" }));
    CHECK_EQ(h.providerOf("b.one"), std::string(""));
}
TEST("taken ids") {
    Host h{ 1 };
    h.addFile(P("a", {}, { "a.x" }));
    h.startAll();
    h.addFile(P("a", {}, { "a.x", "a.x" }));
    CHECK_EQ(h.reload("a"), (Lines{ "stop a", "skip a: a.x is taken" }));
    CHECK(h.running().empty()); CHECK_EQ(h.providerOf("a.x"), std::string(""));
}
TEST("cycles") {
    Host h{ 1 };
    h.addFile(P("x", { "y" }, {})); h.addFile(P("y", { "x" }, {})); h.addFile(P("z", {}, {}));
    const Lines log = h.startAll();
    CHECK_EQ(h.running(), (Lines{ "z" }));
    CHECK(std::find(log.begin(), log.end(), std::string("skip y: cycle")) != log.end());
    CHECK(std::find(log.begin(), log.end(), std::string("skip x: needs y")) != log.end());
}
TEST("reload of a stopped plugin") { Host h{ 1 }; h.addFile(P("a", {}, {}, 2)); CHECK_EQ(h.startAll(), (Lines{ "skip a: API version 2, need 1" })); h.addFile(P("a", {}, {})); CHECK_EQ(h.reload("a"), (Lines{ "start a" })); }

